$adminTitle='Projects';$errors=[];$edit=null;$projectImages=[];
if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();if($edit){$st=db()->prepare('SELECT * FROM project_images WHERE project_id=? ORDER BY sort_order,id');$st->execute([$edit['id']]);$projectImages=$st->fetchAll();}}
if(is_post()){
 verify_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){$id=(int)$_POST['id'];$stmt=db()->prepare('SELECT cover_image FROM projects WHERE id=?');$stmt->execute([$id]);$row=$stmt->fetch();if($row)delete_uploaded_file($row['cover_image']);$st=db()->prepare('SELECT image_path FROM project_images WHERE project_id=?');$st->execute([$id]);foreach($st->fetchAll() as $img)delete_uploaded_file($img['image_path']);db()->prepare('DELETE FROM projects WHERE id=?')->execute([$id]);flash('success','Project deleted.');redirect('admin/projects.php');}
 if($action==='delete_image'){$imgId=(int)$_POST['image_id'];$stmt=db()->prepare('SELECT image_path,project_id FROM project_images WHERE id=?');$stmt->execute([$imgId]);$img=$stmt->fetch();if($img){delete_uploaded_file($img['image_path']);db()->prepare('DELETE FROM project_images WHERE id=?')->execute([$imgId]);flash('success','Project image removed.');redirect('admin/projects.php?edit='.(int)$img['project_id']);}}
 $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$category=trim($_POST['category']??'');$projectStatus=$_POST['project_status']??'Completed';$location=trim($_POST['location']??'');$year=trim($_POST['completed_year']??'');$area=(float)($_POST['area_sqft']??0);$description=trim($_POST['description']??'');$featured=isset($_POST['is_featured'])?1:0;$status=$_POST['status']??'published';$oldImage=$_POST['old_image']??null;
 if($title==='')$errors[]='Project title is required.';if($category==='')$errors[]='Category is required.';if($description==='')$errors[]='Description is required.';
 try{$cover=upload_image($_FILES['cover_image']??[],'projects',$oldImage);}catch(Throwable $e){$errors[]=$e->getMessage();$cover=$oldImage;}
 if(!$errors){$slug=unique_slug('projects',$title,$id?:null);if($id){$stmt=db()->prepare('UPDATE projects SET title=?,slug=?,category=?,project_status=?,location=?,completed_year=?,area_sqft=?,description=?,cover_image=?,is_featured=?,status=? WHERE id=?');$stmt->execute([$title,$slug,$category,$projectStatus,$location,$year,$area?:null,$description,$cover,$featured,$status,$id]);$projectId=$id;}else{$stmt=db()->prepare('INSERT INTO projects(title,slug,category,project_status,location,completed_year,area_sqft,description,cover_image,is_featured,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$title,$slug,$category,$projectStatus,$location,$year,$area?:null,$description,$cover,$featured,$status]);$projectId=(int)db()->lastInsertId();}
  if(!empty($_FILES['gallery_images']['name'][0])){foreach($_FILES['gallery_images']['name'] as $i=>$name){$file=['name'=>$name,'type'=>$_FILES['gallery_images']['type'][$i],'tmp_name'=>$_FILES['gallery_images']['tmp_name'][$i],'error'=>$_FILES['gallery_images']['error'][$i],'size'=>$_FILES['gallery_images']['size'][$i]];try{$path=upload_image($file,'projects');db()->prepare('INSERT INTO project_images(project_id,image_path,sort_order) VALUES(?,?,?)')->execute([$projectId,$path,$i]);}catch(Throwable $e){flash('error','Project saved, but one gallery image failed: '.$e->getMessage());}}}
  flash('success','Project saved successfully.');redirect('admin/projects.php');}
 $edit=['id'=>$id,'title'=>$title,'category'=>$category,'project_status'=>$projectStatus,'location'=>$location,'completed_year'=>$year,'area_sqft'=>$area,'description'=>$description,'cover_image'=>$cover,'is_featured'=>$featured,'status'=>$status];
}
