<div class="grid gap-7 xl:grid-cols-[500px_1fr]"><section class="admin-card p-6"><h2 class="font-display text-2xl font-bold uppercase text-brand-950"><?= $edit?'Edit Project':'Add Project' ?></h2><?php if($errors): ?><div class="mt-4 rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="mt-6 grid gap-4 sm:grid-cols-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="old_image" value="<?= e($edit['cover_image']??'') ?>"><label class="grid gap-2 text-sm font-bold sm:col-span-2">Project Title<input class="form-input" name="title" value="<?= e($edit['title']??'') ?>" required></label><label class="grid gap-2 text-sm font-bold">Category<input class="form-input" name="category" value="<?= e($edit['category']??'Residential') ?>" list="project-categories" required><datalist id="project-categories"><option>Residential</option><option>Commercial</option><option>Infrastructure</option><option>Renovation</option><option>Interiors</option></datalist></label><label class="grid gap-2 text-sm font-bold">Project Status<select class="form-input" name="project_status"><option <?= ($edit['project_status']??'')==='Completed'?'selected':'' ?>>Completed</option><option <?= ($edit['project_status']??'')==='Ongoing'?'selected':'' ?>>Ongoing</option></select></label><label class="grid gap-2 text-sm font-bold">Location<input class="form-input" name="location" value="<?= e($edit['location']??'') ?>"></label><label class="grid gap-2 text-sm font-bold">Year<input class="form-input" name="completed_year" value="<?= e($edit['completed_year']??date('Y')) ?>"></label><label class="grid gap-2 text-sm font-bold">Area (sq.ft.)<input type="number" step="0.01" class="form-input" name="area_sqft" value="<?= e($edit['area_sqft']??'') ?>"></label><label class="grid gap-2 text-sm font-bold">Publish Status<select class="form-input" name="status"><option value="published" <?= ($edit['status']??'published')==='published'?'selected':'' ?>>Published</option><option value="draft" <?= ($edit['status']??'')==='draft'?'selected':'' ?>>Draft</option></select></label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Description<textarea class="form-input min-h-40" name="description" required><?= e($edit['description']??'') ?></textarea></label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Cover Image<input type="file" class="form-input" name="cover_image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($edit['cover_image'])): ?><img src="<?= upload_url($edit['cover_image']) ?>" class="mt-2 h-32 w-full rounded-xl object-cover"><?php endif; ?></label><label class="grid gap-2 text-sm font-bold sm:col-span-2">Additional Gallery Images<input type="file" class="form-input" name="gallery_images[]" multiple accept="image/jpeg,image/png,image/webp"></label><label class="flex items-center gap-3 text-sm font-bold sm:col-span-2"><input type="checkbox" name="is_featured" class="h-5 w-5" <?= ($edit['is_featured']??0)?'checked':'' ?>>Feature on homepage</label><div class="flex gap-3 sm:col-span-2"><button class="rounded-xl bg-brand-700 px-5 py-3 font-extrabold text-white">Save Project</button><?php if($edit): ?><a href="<?= url('admin/projects.php') ?>" class="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</a><?php endif; ?></div></form><?php if($projectImages): ?><div class="mt-7 border-t border-slate-100 pt-6"><h3 class="font-extrabold text-brand-950">Current Gallery</h3><div class="mt-3 grid grid-cols-3 gap-3"><?php foreach($projectImages as $img): ?><div class="relative"><img src="<?= upload_url($img['image_path']) ?>" class="aspect-square w-full rounded-xl object-cover"><form method="post" data-confirm="Remove this image?" class="absolute right-1 top-1"><?= csrf_field() ?><input type="hidden" name="action" value="delete_image"><input type="hidden" name="image_id" value="<?= (int)$img['id'] ?>"><button class="rounded-lg bg-red-600 p-1.5 text-white"><i data-lucide="x" class="h-4 w-4"></i></button></form></div><?php endforeach; ?></div></div><?php endif; ?></section><section class="admin-card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl font-bold uppercase text-brand-950">All Projects</h2><span class="text-sm font-bold text-slate-400"><?= count($projects) ?> items</span></div><div class="table-wrap mt-5"><table class="admin-table"><thead><tr><th>Project</th><th>Status</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach($projects as $project): ?><tr><td><div class="flex min-w-64 items-center gap-3"><img src="<?= upload_url($project['cover_image']) ?>" class="h-14 w-20 rounded-xl object-cover"><div><div class="font-extrabold text-brand-950"><?= e($project['title']) ?></div><div class="text-xs text-slate-500"><?= e($project['category']) ?> · <?= e($project['location']) ?></div></div></div></td><td><span class="status-badge <?= $project['project_status']==='Ongoing'?'bg-amber-100 text-amber-700':'bg-emerald-100 text-emerald-700' ?>"><?= e($project['project_status']) ?></span></td><td><?= e(ucfirst($project['status'])) ?></td><td><div class="flex gap-2"><a href="?edit=<?= (int)$project['id'] ?>" class="rounded-lg bg-blue-50 p-2 text-blue-700"><i data-lucide="pencil" class="h-4 w-4"></i></a><form method="post" data-confirm="Delete this project and its images?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$project['id'] ?>"><button class="rounded-lg bg-red-50 p-2 text-red-700"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
